import re

import django.db.models.deletion
from django.db import migrations, models

GAP_MARKER_PATTERN = re.compile(r'\[\[(\d+)\]\]')


def gaps_to_blocks(apps, schema_editor):
    Task = apps.get_model('tasks', 'Task')
    TaskGap = apps.get_model('tasks', 'TaskGap')
    TaskBlock = apps.get_model('tasks', 'TaskBlock')

    for task in Task.objects.filter(type='gap'):
        gaps = {gap.number: gap for gap in TaskGap.objects.filter(task=task)}
        body = task.body or ''
        matches = list(GAP_MARKER_PATTERN.finditer(body))
        blocks = []
        order = 0

        if matches:
            position = 0
            for match in matches:
                before = body[position:match.start()].strip()
                if before:
                    blocks.append(TaskBlock(
                        task=task, kind='text', text=before, order=order,
                    ))
                    order += 1
                number = int(match.group(1))
                gap = gaps.pop(number, None)
                if gap is not None:
                    blocks.append(TaskBlock(
                        task=task, kind='gap', answers=gap.answers, order=order,
                    ))
                else:
                    blocks.append(TaskBlock(
                        task=task, kind='text', text=match.group(0), order=order,
                    ))
                order += 1
                position = match.end()
            rest = body[position:].strip()
            if rest:
                blocks.append(TaskBlock(
                    task=task, kind='text', text=rest, order=order,
                ))
                order += 1
            task.body = ''
            task.save(update_fields=['body'])

        for number in sorted(gaps):
            blocks.append(TaskBlock(
                task=task, kind='gap', answers=gaps[number].answers, order=order,
            ))
            order += 1

        TaskBlock.objects.bulk_create(blocks)


